"""Point each kit at the shared audit spool and record where to read it.

The store itself stays under the engine state directory, mode 0700. Apps
receive only a spool directory they can append to.
"""

from __future__ import annotations

import os
from pathlib import Path
from typing import Any

import yaml

from scripts.audit_store import RETENTION_DEFAULT_DAYS, RETENTION_MAX_DAYS, RETENTION_MIN_DAYS, audit_dir, ensure_layout
from scripts.oidc_wire import resolve_kit_path, to_bool, write_sidecar

AUDIT_HEADER = (
    "# Generated by easydeploy-engine. Do not edit.\n"
    "# Disable with audit.enabled: false in engine.yaml, then re-apply.\n"
)

CONTAINER_DIR = "/var/lib/easydeploy-audit"
OPENCLOUD_SIDECAR = ".opencloud-easy-deploy/integration/audit.yaml"
MATRIX_SPOOL_LINK = Path("modules/core/audit-spool")

CONTAINERS = {
    "kanidm": ("kanidm", "kanidm"),
    "stalwart": ("stalwart", "stalwart"),
    "matrix": ("matrix_mas", "mas"),
}


def audit_settings(config: dict) -> dict[str, Any]:
    raw = config.get("audit")
    if raw is None:
        raw = {}
    if not isinstance(raw, dict):
        raise ValueError("audit must be a mapping")
    enabled = True if "enabled" not in raw else to_bool(raw.get("enabled"))
    try:
        days = int(raw.get("retention_days", RETENTION_DEFAULT_DAYS))
    except (TypeError, ValueError) as exc:
        raise ValueError("audit.retention_days must be an integer") from exc
    if days < RETENTION_MIN_DAYS or days > RETENTION_MAX_DAYS:
        raise ValueError(
            f"audit.retention_days must be between {RETENTION_MIN_DAYS} and {RETENTION_MAX_DAYS}"
        )
    return {
        "enabled": enabled,
        "retention_days": days,
        "hold": to_bool(raw.get("hold")),
    }


def sources_path(project_root: Path) -> Path:
    return audit_dir(project_root) / "sources.yaml"


def load_sources(project_root: Path) -> dict[str, Any]:
    path = sources_path(project_root)
    if not path.is_file():
        return {"files": [], "containers": []}
    data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    if not isinstance(data, dict):
        raise ValueError(f"{path}: root must be a mapping")
    return data


def _spool(project_root: Path, name: str) -> Path:
    path = audit_dir(project_root) / "spool" / name
    path.mkdir(parents=True, exist_ok=True)
    os.chmod(path, 0o1777)
    return path


def _kit_root(service: dict, project_root: Path) -> Path | None:
    try:
        root = resolve_kit_path(service, project_root)
    except (OSError, ValueError):
        return None
    if not root.is_dir():
        return None
    return root


def _remove(path: Path) -> None:
    if path.is_file() or path.is_symlink():
        path.unlink()


def _link_spool(link: Path, target: Path) -> None:
    link.parent.mkdir(parents=True, exist_ok=True)
    if link.is_symlink():
        if link.resolve() == target.resolve():
            return
        link.unlink()
    elif link.is_dir():
        try:
            next(link.iterdir())
            # Keep an existing spool that already has files; the collector reads it.
            return
        except StopIteration:
            link.rmdir()
    elif link.exists():
        return
    link.symlink_to(target, target_is_directory=True)


def wire_audit(config: dict, enabled: list[dict], project_root: Path) -> list[str]:
    """Write sidecars and sources.yaml. Returns operator-facing notes."""
    settings = audit_settings(config)
    ensure_layout(audit_dir(project_root))
    notes: list[str] = []
    files: list[dict[str, str]] = []
    containers: list[dict[str, str]] = []
    by_name = {service["name"]: service for service in enabled}

    opencloud = by_name.get("opencloud")
    opencloud_root = _kit_root(opencloud, project_root) if opencloud else None
    opencloud_sidecar = opencloud_root / OPENCLOUD_SIDECAR if opencloud_root else None
    if settings["enabled"] and opencloud_root and opencloud_sidecar is not None:
        spool = _spool(project_root, "opencloud")
        write_sidecar(
            opencloud_sidecar,
            {"enabled": True, "spool_dir": str(spool)},
            header=AUDIT_HEADER,
        )
        files.append(
            {
                "path": str(spool / "opencloud.jsonl"),
                "kind": "opencloud",
                "source": "opencloud",
            }
        )
        notes.append(f"Audit: OpenCloud file access -> {spool}")
    elif opencloud_sidecar is not None:
        _remove(opencloud_sidecar)

    matrix = by_name.get("matrix")
    matrix_root = _kit_root(matrix, project_root) if matrix else None
    if settings["enabled"] and matrix_root is not None:
        spool = _spool(project_root, "matrix")
        link = matrix_root / MATRIX_SPOOL_LINK
        _link_spool(link, spool)
        read_path = spool / "synapse.jsonl"
        if link.is_dir() and not link.is_symlink():
            read_path = link / "synapse.jsonl"
        files.append({"path": str(read_path), "kind": "synapse", "source": "matrix"})
        notes.append(f"Audit: Matrix logins and membership -> {read_path.parent}")

    if settings["enabled"]:
        for service_name, (container, kind) in CONTAINERS.items():
            if service_name not in by_name:
                continue
            containers.append({"name": container, "kind": kind, "source": service_name if service_name != "matrix" else "matrix"})

    payload = {
        "enabled": settings["enabled"],
        "retention_days": settings["retention_days"],
        "hold": settings["hold"],
        "files": files,
        "containers": containers,
    }
    path = sources_path(project_root)
    path.write_text(
        "# Generated by easydeploy-engine.\n"
        + yaml.safe_dump(payload, sort_keys=False),
        encoding="utf-8",
    )
    os.chmod(path, 0o600)
    if settings["enabled"]:
        hold = ", hold on" if settings["hold"] else ""
        notes.append(
            f"Audit store: {audit_dir(project_root)} "
            f"(keep {settings['retention_days']} days{hold}). Query with: bash audit.sh query --help"
        )
    else:
        notes.append("Audit: disabled")
    return notes
